using System;
using System.Reflection;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonDispatchNavigationVerification
    {
        static void Check(bool value,string message){if(!value)throw new Exception(message);}
        public static void BuildAndVerify()
        {
            PythonDispatchLayout.Build();var p=UnityEngine.Object.FindObjectOfType<ContentPreview>();p.Initialize();var client=p.GetComponent<PythonStateClient>();var f=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(client,p);var state=PythonServiceSetup.Sample();state.instance_id="dispatch-navigation";state.can_set_shifts=true;state.required_action="";state.funds=3000;var a=state.cats[0];var b=state.cats[1];
            Func<PythonCatState,PythonDispatchComparisonCat> comparisonCat=cat=>new PythonDispatchComparisonCat{cat_id=cat.cat_id,name=cat.name,status="在店",rows=new[]{new PythonDispatchComparisonRow{kind="general",choice="near",label="近所のお店",cost=10,days=1,reward=120,can_select=true,unlock="最初から利用可能",details="近所のお店\n費用10 / 帰還まで1回の閉店\n報酬120 / 歓迎条件：なし\n最初から利用可能"},new PythonDispatchComparisonRow{kind="general",choice="studio",label="撮影スタジオ",cost=50,days=2,reward=240,can_select=false,reason="人気150が必要です。",unlock="人気150",details="撮影スタジオ\n費用50 / 帰還まで2回の閉店\n報酬240\n人気150が必要です。"},new PythonDispatchComparisonRow{kind="patron",choice="patron",label="有力者訪問",cost=20,days=2,reward=220,satisfaction=30,can_select=true,details="有力者訪問\n費用20 / 帰還まで2回の閉店\n報酬220 / 満足度加点30"}}};
            state.dispatch_comparison=new PythonDispatchComparison{cats=new[]{comparisonCat(a),comparisonCat(b)},notes="条件と報酬は出発時に固定します。"};state.general_dispatch=new PythonPatronDispatch{options=new[]{a,b}.SelectMany(cat=>new[]{new PythonDispatchOption{cat_id=cat.cat_id,choice="near",label=cat.name+" / 近所のお店",days=1,reward=120,can_select=true,detail="健康・体力あり / 店内に席数分の猫を残します。"},new PythonDispatchOption{cat_id=cat.cat_id,choice="studio",label=cat.name+" / 撮影スタジオ",days=2,reward=240,can_select=false,reason="人気150が必要です。",detail="人気150が必要です。"}}).ToArray(),events=new PythonDispatchEvent[0]};state.patron_dispatch=new PythonPatronDispatch{options=new[]{a,b}.Select(cat=>new PythonDispatchOption{cat_id=cat.cat_id,choice="patron",label=cat.name+" / 有力者訪問",days=2,reward=220,satisfaction=30,can_select=true,detail="歓迎条件：白い毛 / 得意分野 接客"}).ToArray(),events=new PythonDispatchEvent[0]};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});apply();p.GetComponent<PythonPreparationPanel>().Close();var menu=p.GetComponent<PythonMenuPanel>();var comparison=p.GetComponent<PythonDispatchComparisonPanel>();var general=p.GetComponent<PythonGeneralDispatchPanel>();var patron=p.GetComponent<PythonDispatchPanel>();
            menu.Open();menu.SelectGroup(1);menu.entries[10].onClick.Invoke();comparison.cats.value=1;Check(comparison.SelectedCatId==b.cat_id,"Comparison cat selection failed");comparison.proceed.onClick.Invoke();Check(general.panel.activeSelf && general.SelectedCatId==b.cat_id && general.SelectedDestination=="near","Comparison to general lost selection");Check(general.close.GetComponentInChildren<Text>().text=="メニューへ戻る","General menu return lost");Capture(p,"DispatchGeneralUI");general.compare.onClick.Invoke();Check(comparison.panel.activeSelf && !general.panel.activeSelf && comparison.SelectedCatId==b.cat_id && comparison.SelectedDestination=="near","General to comparison lost selection");comparison.destinations.value=2;comparison.proceed.onClick.Invoke();Check(patron.panel.activeSelf && patron.SelectedCatId==b.cat_id && patron.SelectedDestination=="patron","Comparison to patron lost selection");Capture(p,"DispatchPatronUI");patron.compare.onClick.Invoke();Check(comparison.SelectedCatId==b.cat_id && comparison.SelectedDestination=="patron","Patron to comparison lost selection");Capture(p,"DispatchComparisonUI");comparison.close.onClick.Invoke();Check(menu.panel.activeSelf && menu.SelectedGroup==1,"Dispatch menu category lost");
            menu.Close();p.GetComponent<PythonCatDetailsPanel>().Open(b.cat_id);general.Open(b.cat_id);Check(general.SelectedCatId==b.cat_id && general.destinations.options.All(o=>o.text.Contains(b.name)),"General ignored detail cat");general.cats.value=0;Check(general.SelectedCatId==a.cat_id && general.destinations.options.All(o=>o.text.Contains(a.name)),"General cat switch mixed options");general.destinations.value=1;Check(!general.send.interactable && general.details.text.Contains("人気150"),"Disabled destination reason missing");general.destinations.value=0;Check(general.summary.text.Contains("費用：10") && general.details.text.Contains("報酬：120"),"Dispatch cost/reward missing");
            state.general_dispatch.options=state.general_dispatch.options.Reverse().ToArray();state.revision++;apply();Check(general.SelectedCatId==a.cat_id && general.SelectedDestination=="near","Polling reordered destination selection");general.compare.onClick.Invoke();Check(comparison.SelectedCatId==a.cat_id && comparison.SelectedDestination=="near","Polling lost comparison context");comparison.Close();general.Open(a.cat_id);
            state.general_dispatch.events=new[]{new PythonDispatchEvent{cat_id=a.cat_id,choice="g-travel",label=a.name+" / 近所のお店",status="travelling",remaining=1,reward=120,reason="まだ帰還していません。"},new PythonDispatchEvent{cat_id=b.cat_id,choice="g-return",label=b.name+" / 近所のお店",status="waiting",reward=120,can_select=true,detail="用品報酬：ケア用品（未受取）"}};state.revision++;apply();Check(general.SelectedCatId==b.cat_id && general.receive.interactable && general.progress.text.Contains("帰還待ち"),"Pending return cat not focused");Capture(p,"DispatchReturnUI");general.cats.value=0;Check(general.SelectedCatId==a.cat_id && !general.receive.interactable && general.progress.text.Contains("あと 1") && general.progress.text.Contains("まだ帰還"),"Travelling status/guard missing");apply();Check(general.SelectedCatId==a.cat_id,"Polling forced waiting cat repeatedly");general.OpenReturn("g-return");Check(general.SelectedCatId==b.cat_id && general.receive.interactable,"Specific return lost cat");
            var adopted=state.cats[2];adopted.activity="adopted";adopted.activity_label="譲渡済み";var adoptedComparison=comparisonCat(adopted);foreach(var row in adoptedComparison.rows){row.can_select=false;row.reason="譲渡済みの猫です。";}state.dispatch_comparison.cats=state.dispatch_comparison.cats.Concat(new[]{adoptedComparison}).ToArray();state.revision++;apply();comparison.OpenOption(adopted.cat_id,"general","near");comparison.Proceed();Check(general.SelectedCatId==adopted.cat_id && !general.send.interactable,"Adopted comparison silently selected another cat");general.OpenReturn("g-return");
            general.Disconnect();patron.Disconnect();comparison.Disconnect();Check(!general.send.interactable && !general.receive.interactable && !general.compare.interactable && !patron.send.interactable && !comparison.proceed.interactable,"Offline dispatch allowed");apply();
            Action<string,string,Action> queue=(kind,catId,send)=>{send();var command=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);Check(command!=null && command.kind==kind && command.cat_id==catId,"Wrong dispatch command "+kind);typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);state.revision++;apply();};
            general.OpenOption(b.cat_id,"near");queue("dispatch_general",b.cat_id,general.Send);general.OpenReturn("g-return");general.Receive();var returned=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);Check(returned!=null && returned.kind=="receive_general" && returned.choice=="g-return","Wrong return command");typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);state.general_dispatch.events[1].status="resolved";state.general_dispatch.events[1].can_select=false;state.general_dispatch.events[1].detail="用品報酬：ケア用品（受取済み）";state.revision++;apply();Check(!general.receive.interactable && general.progress.text.Contains("受取済み"),"Resolved return still enabled");patron.OpenOption(b.cat_id,"patron");queue("dispatch_patron",b.cat_id,patron.Send);
            state.patron_dispatch.events=new[]{new PythonDispatchEvent{cat_id=b.cat_id,choice="p-return",label=b.name+" / 有力者",status="waiting",reward=220,satisfaction=30,can_select=true}};state.revision++;apply();Check(patron.SelectedCatId==b.cat_id && patron.receive.interactable && !patron.close.interactable && patron.progress.text.Contains("満足度"),"Patron waiting guard changed");patron.Receive();returned=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);Check(returned!=null && returned.kind=="receive_patron" && returned.choice=="p-return","Wrong patron return command");typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);state.patron_dispatch.events[0].status="resolved";state.patron_dispatch.events[0].can_select=false;state.revision++;apply();
            state.general_dispatch.events=new[]{new PythonDispatchEvent{cat_id=b.cat_id,choice="g-choice",label=b.name+" / 途中イベント",status="travelling",needs_response=true,remaining=2,reason="途中の選択イベントに回答してください。"}};state.revision++;apply();Check(general.SelectedCatId==b.cat_id && !general.receive.interactable && general.progress.text.Contains("選択待ち"),"Dispatch choice bypassed return guard");state.general_dispatch.events[0].status="missing";state.general_dispatch.events[0].needs_response=false;state.general_dispatch.events[0].reason="宿のトラブルに対応してください。";state.revision++;apply();Check(!general.receive.interactable && general.progress.text.Contains("行方不明") && general.progress.text.Contains("宿のトラブル"),"Missing dispatch reason absent");
            comparison.ResetSelection();general.ResetSelection();patron.ResetSelection();Check(!comparison.panel.activeSelf && !general.panel.activeSelf && !patron.panel.activeSelf,"Load reset retained dispatch panel");state.instance_id="loaded-game";state.general_dispatch.events=new PythonDispatchEvent[0];state.patron_dispatch.events=new PythonDispatchEvent[0];apply();Check(!general.panel.activeSelf && !patron.panel.activeSelf,"Instance reset retained panels");state.dispatch_comparison=new PythonDispatchComparison{cats=new PythonDispatchComparisonCat[0]};state.general_dispatch.options=new PythonDispatchOption[0];state.patron_dispatch.options=new PythonDispatchOption[0];state.revision++;apply();comparison.Open();Check(!comparison.proceed.interactable,"Empty comparison enabled");general.Open(a.cat_id);Check(!general.send.interactable && !general.receive.interactable,"Empty dispatch enabled");Check(typeof(PythonStateClient).GetField("pending",f).GetValue(client)==null,"Browsing sent command");Debug.Log("CAT_CAFE_DISPATCH_NAVIGATION_OK: same cat / options / comparison round trip / menu / costs / conditions / reordered polling / return focus / offline / send and receive commands / reset");
        }
        static void Capture(ContentPreview p,string name){Canvas.ForceUpdateCanvases();foreach(var text in p.GetComponents<PythonGeneralDispatchPanel>().Select(v=>v.summary).Concat(p.GetComponents<PythonDispatchPanel>().Select(v=>v.summary)).Concat(p.GetComponents<PythonDispatchComparisonPanel>().Select(v=>v.summary)))if(text!=null && text.gameObject.activeInHierarchy)Check(text.preferredHeight<=text.rectTransform.rect.height+1,"Dispatch summary clipped");typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p,"Logs/"+name+".png"});}
    }
}
